 function lay_c(k: Kind): string {
@@ -2600,6 +2603,11 @@
   const word = WORDS[adt.k];
   if (word !== undefined) {
     const vs = emit_each(sc, flds, [], tys());
+    // Word packing needs structural bits, never a partially boxed bit tail.
+    if (word === W32) {
+      const lays = lay_node(x.k).arms![x.k];
